"""Read-only native trace queries and bounded CPU parameter contribution checks."""
from functools import lru_cache
from pathlib import Path
import json
import numpy as np
from fastapi import APIRouter,HTTPException,Query
from shared.dist_protocol.mechanism_trace import TraceStore,unbits

router=APIRouter(prefix='/api/traces',tags=['native-mechanism-traces'])
_store=None


def store():
    global _store
    if _store is None:_store=TraceStore()
    return _store


def checked(fn,*args,**kwargs):
    try:return fn(*args,**kwargs)
    except KeyError as e:raise HTTPException(409,str(e)) from e
    except (ValueError,OSError) as e:raise HTTPException(422,str(e)) from e


@router.get('/catalog')
def catalog(run_id:str='',parent:str=''):
    if parent:
        checked(store().manifest,parent)
        with store().db() as db:rows=db.execute("SELECT body FROM traces WHERE json_extract(body,'$.parent_trace_id')=? ORDER BY created",(parent,)).fetchall()
        return {'traces':[{'trace_id':d['trace_id'],'sample_id':d['sample_id'],'generation_step':d.get('generation_step',0),'n_tokens':d['n_tokens']} for r in rows for d in [json.loads(r['body'])]]}
    d=store().catalog(run_id);d['traces']=[r for r in d['traces'] if ':G' not in r['sample_id']];return d


@router.get('/history')
def history():
    p=Path(__file__).resolve().parents[1]/'research/phase2793/history-index.research.json'
    return json.loads(p.read_text(encoding='utf-8')) if p.is_file() else {'entries':[],'state':'not_migrated'}


@router.get('/context')
def context(run_id:str):
    if run_id=='NMLP-LONG-20261104-v1':
        p=Path(__file__).resolve().parents[1]/'research/native_mlp_long/v1/unified-evidence.research.json'
        if not p.is_file():raise HTTPException(404,'原生MLP长文本证据尚未归档。')
        return json.loads(p.read_text(encoding='utf-8'))
    folder={'P2793-ENTITY-ARBITRATION-v1':'phase2793','P2794-ATOMIC-ARBITRATION-v4':'phase2794'}.get(run_id)
    if folder is None:raise HTTPException(404,'该运行暂无统一研究上下文。')
    p=Path(__file__).resolve().parents[1]/'research'/folder/'unified-evidence.research.json'
    if not p.is_file():raise HTTPException(404,'研究上下文尚未归档。')
    return json.loads(p.read_text(encoding='utf-8'))


@router.get('/profile')
def profile(run_id:str,block:int=Query(0,ge=0,le=35),space:str='mlp'):
    ctx=context(run_id)
    if ctx.get('study_type')=='native_mlp_long':raise HTTPException(404,'自然语料研究没有文档−现实剖面；请查询对应原生单元说明书。')
    if space not in ['mlp','hidden']:raise HTTPException(422,'只支持原生mlp/hidden空间。')
    folder='phase2793_arbitration' if run_id=='P2793-ENTITY-ARBITRATION-v1' else 'phase2794_arbitration_v4'
    p=Path(__file__).resolve().parents[1]/'tests/glm5/result'/folder/'native-profiles.npz'
    if not p.is_file():raise HTTPException(404,'本节点没有原生响应剖面。')
    with np.load(p) as z:
        if 'profile_block' in z and int(z['profile_block'])!=block:raise HTTPException(404,f'本运行响应剖面仅分析发现集选定的块{int(z["profile_block"])}，其他块的原生阵列仍可查询。')
        disc=z[space+'_discovery_delta'][block];held=z[space+'_heldout_delta'][block]
    return {'schema':'mechanism_response_profile.v1','kind':'real','run_id':run_id,'block':block,'space':space,
        'discovery_delta':disc.tolist(),'heldout_delta':held.tolist(),'n_discovery_entities':ctx.get('n_discovery_entities',16),'n_heldout_entities':ctx.get('n_heldout_entities',32),
        'boundary':'mlp.down_proj.input' if space=='mlp' else f'hidden_states[{block if run_id=="P2793-ENTITY-ARBITRATION-v1" else block+1}]',
        'interpretation':'Document-minus-reality scope-prompt response, including errors; descriptive only, no FWER-controlled semantic or causal claim.'}


@router.get('/{trace_id}/manifest')
def manifest(trace_id:str):return checked(store().manifest,trace_id)[0]


@router.get('/{trace_id}/field')
def field(trace_id:str,block:int=Query(0,ge=0),position:int=Query(...,ge=0),boundary:str='mlp_activation'):
    if boundary in ['hidden_state','embedding']:return checked(hidden_at,trace_id,0 if boundary=='embedding' else block,position)
    return checked(store().field,trace_id,block,position,boundary)


def hidden_at(trace_id,layer,position):
    d,_=store().manifest(trace_id)
    if not d.get('parent_trace_id'):return store().hidden(trace_id,layer,position)
    # Cached generation forwards contain only the newly evaluated token, while
    # manifest positions refer to the complete absolute token history.
    if not 0<=layer<=d['n_layers']:raise ValueError('hidden layer outside trace')
    if position not in d['readout_positions']:raise KeyError('cached forward did not recapture this historical token')
    a=np.load(store().native_path(trace_id,'hidden_readouts.npy'),mmap_mode='r')
    v=unbits(a[layer,d['readout_positions'].index(position)])
    return {'schema':'mechanism_field.v1','trace_id':trace_id,'layer':layer,'position':position,
        'boundary':'embedding' if layer==0 else 'hidden_state','shape':[len(v)],'values':v.tolist(),'source':'native_BF16_bits_cached_current_token'}


@router.get('/{trace_id}/attention-row')
def attention_row(trace_id:str,block:int=Query(0,ge=0),head:int=Query(0,ge=0),query:int=Query(...,ge=0)):
    d,_=checked(store().manifest,trace_id)
    if d.get('parent_trace_id') and query not in d['readout_positions']:raise HTTPException(409,'缓存生成步仅重新采集当前query；历史query请查前缀轨迹。')
    return checked(store().attention_row,trace_id,block,head,query)


def trace_model(d):
    from deploy.parameter_service import catalog
    from deploy.parameter_reader import model_snapshot
    preferred=d.get('provenance',{}).get('model_path','')
    models=sorted(catalog(),key=lambda m:str(m['_path']).replace('\\','/').lower()!=preferred.replace('\\','/').lower())
    for m in models:
        if m['config']['hidden_size']!=d['d_model'] or m['config']['num_hidden_layers']!=d['n_layers']:continue
        if model_snapshot(m['_path'])['sha256']==d['model_snapshot']:return m
    raise ValueError('no configured local weights match the complete trace snapshot')


@lru_cache(maxsize=8)
def tensor_file(folder,name):
    from deploy.parameter_reader import header
    for p in sorted(Path(folder).glob('*.safetensors')):
        h,_,_=header(p)
        if name in h:return str(p)
    raise ValueError('parameter tensor missing')


def parameter(folder,name,index):
    from safetensors import safe_open
    # Reads only selected rows/columns on CPU; no loaded research model/GPU.
    with safe_open(tensor_file(str(folder),name),framework='pt',device='cpu') as f:
        x=f.get_slice(name)[index]
    return x.float().numpy()


def contributions(trace_id,block,position,head,unit,coordinate):
    d,_=store().manifest(trace_id)
    if not 0<=block<d['n_layers'] or not 0<=head<d['n_heads'] or not 0<=unit<d['d_ff'] or not 0<=coordinate<d['d_model']:raise ValueError('index outside native dimensions')
    if position not in d['readout_positions']:raise KeyError('module source decomposition not captured at selected query')
    m=trace_model(d);folder=m['_path'];z=store().block(trace_id,block);r=d['readout_positions'].index(position)
    vals={k:unbits(z[k][r]) for k in ['gate','value','activation','mlp_input','head_z','attention_output','mlp_output','resid_in']}
    prefix=f'model.layers.{block}.';gate=parameter(folder,prefix+'mlp.gate_proj.weight',(unit,slice(None)))
    up=parameter(folder,prefix+'mlp.up_proj.weight',(unit,slice(None)))
    down=parameter(folder,prefix+'mlp.down_proj.weight',(coordinate,slice(None)))
    orow=parameter(folder,prefix+'self_attn.o_proj.weight',(coordinate,slice(None)))
    gt=gate*vals['mlp_input'];ut=up*vals['mlp_input'];dt=down*vals['activation']
    heads=(orow.reshape(d['n_heads'],d['head_dim'])*vals['head_z']).sum(-1)
    # Decompose this unit's gate input with the actual sample RMS held fixed.
    import torch
    mid=(torch.from_numpy(vals['resid_in']).to(torch.bfloat16)+torch.from_numpy(vals['attention_output']).to(torch.bfloat16)).float().numpy()
    gamma=parameter(folder,prefix+'post_attention_layernorm.weight',slice(None))
    read=gate*gamma/np.sqrt(np.mean(mid**2)+m['config']['rms_norm_eps'])
    omatrix=parameter(folder,prefix+'self_attn.o_proj.weight',(slice(None),slice(None)))
    readheads=(omatrix.T@read).reshape(d['n_heads'],d['head_dim'])
    hg=(readheads*vals['head_z']).sum(-1);residual=float(read@vals['resid_in'])
    source=None
    if d['deep']:
        weights=np.asarray(store().attention_row(trace_id,block,head,position)['weights'])
        group=head//(d['n_heads']//d['n_kv_heads']);v=unbits(z['v'][group])
        source=(weights*(v@orow.reshape(d['n_heads'],d['head_dim'])[head])).tolist()
    return {'schema':'mechanism_connections.v1','kind':'real','trace_id':trace_id,'model_snapshot':d['model_snapshot'],
        'local_model_id':m['id'],'verified_full_snapshot':True,'block':block,'position':position,'head':head,'unit':unit,'coordinate':coordinate,
        'gate_terms':gt.tolist(),'value_terms':ut.tolist(),'mlp_output_terms':dt.tolist(),'head_output_terms':heads.tolist(),
        'head_gate_terms':hg.tolist(),'residual_gate_term':residual,'source_token_terms':source,
        'observed':{'gate':float(vals['gate'][unit]),'value':float(vals['value'][unit]),'activation':float(vals['activation'][unit]),
            'mlp_output_coordinate':float(vals['mlp_output'][coordinate]),'attention_output_coordinate':float(vals['attention_output'][coordinate])},
        'reconstructed':{'gate':float(gt.sum(dtype=np.float64)),'value':float(ut.sum(dtype=np.float64)),
            'mlp_output_coordinate':float(dt.sum(dtype=np.float64)),'attention_output_coordinate':float(heads.sum(dtype=np.float64)),
            'gate_via_heads_plus_residual':float(hg.sum(dtype=np.float64)+residual)},
        'source':'exact original parameter slices and native sample responses; FP32 sums vs native BF16 can differ by rounding',
        'edge_types':{'head_to_mlp':'local direct gate-input attribution with actual RMS held fixed; approximate, not causal',
            'mlp_to_output':'sum of all native unit products for selected output coordinate','embedding_to_layers':'residual computational continuity; no direct semantic-causality claim'},
        'causal_evidence':'not established by this arithmetic decomposition'}


@router.get('/{trace_id}/connections')
def connections(trace_id:str,block:int=Query(0,ge=0),position:int=Query(...,ge=0),head:int=Query(0,ge=0),unit:int=Query(0,ge=0),coordinate:int=Query(0,ge=0)):
    return checked(contributions,trace_id,block,position,head,unit,coordinate)

import {useState} from 'react';
import {useApi} from '../app/rdc_fusion/api.js';
import {Empty} from '../app/rdc_fusion/ui.jsx';
import {NativeArray} from './MechanismScene.jsx';

const pct=x=>Number.isFinite(x)?`${(100*x).toFixed(1)}%`:'—';
const num=x=>Number.isFinite(x)?x.toPrecision(4):'—';
const points=x=>Number.isFinite(x)?(100*x).toFixed(2):'—';
const NI={noninferior:'通过非劣效门',inferior:'超过允许损失',inconclusive:'尚未证实能力保持'};
const FOLD=['发现','确认','锁箱'];
const POLE={Gpos:'Gate 正极',Gneg:'Gate 负极',Apos:'A 正极',Aneg:'A 负极'};

function InterventionErrors({doseRef,capabilityRef,inputsRef}){
  const d=useApi(`/api/research-library/artifacts/${doseRef}`),c=useApi(`/api/research-library/artifacts/${capabilityRef}`);
  const inputs=useApi(inputsRef?`/api/research-library/artifacts/${inputsRef}`:null);
  if(d.error||c.error)return <Empty>{d.error||c.error}</Empty>;
  if(!d.data||!c.data)return <p>读取逐条干预与能力记录…</p>;
  const b=new Map(d.data.result.rows.filter(r=>r.condition==='base').map(r=>[r.pair_index,r]));
  const losses=d.data.result.rows.filter(r=>r.condition!=='base'&&b.get(r.pair_index)?.correct&&!r.correct);
  const eb=new Map(c.data.base.map(r=>[r.id,r]));const changes=c.data.edited.filter(r=>eb.get(r.id)?.correct!==r.correct);const questions=new Map((inputs.data?.items||[]).map(q=>[q.id,q]));
  return <><p className="v8-note">自然续写退化记录 {losses.length} 条；能力答案改变 {changes.length} 条（含参考题，逐条标注）。同一输入跨剂量可重复出现。</p>{losses.map((r,i)=><details key={i}><summary>配对 {r.pair_index} · {r.condition} · 原对改错</summary><pre className="v8-artifact-json">{JSON.stringify({base:b.get(r.pair_index),edited:r},null,2)}</pre></details>)}{changes.map(r=><details key={r.id}><summary>{r.id} · {r.gate_eligible?'正式能力题':'参考题不入门'} · {r.correct?'原错改对':'原对改错'}</summary><pre className="v8-artifact-json">{JSON.stringify({question:questions.get(r.id),base:eb.get(r.id),edited:r},null,2)}</pre></details>)}</>;
}

function DosePlot({effects}){
  const names=['base','target_half','target_full'];if(!effects.base)return null;
  const xy=names.map((n,i)=>[60+i*220,130-effects[n].accuracy*100]);
  return <svg viewBox="0 0 570 175" role="img" aria-label="自然续写真实剂量曲线" style={{width:'100%',maxWidth:650,maxHeight:200}}>{[0,.5,1].map(v=><g key={v}><line x1="60" x2="500" y1={130-v*100} y2={130-v*100} stroke="#e2e8f0"/><text x="48" y={134-v*100} textAnchor="end" fontSize="10">{100*v}%</text></g>)}<polyline points={xy.map(p=>p.join(',')).join(' ')} stroke="#2979bf" strokeWidth="2" fill="none"/>{xy.map(([x,y],i)=><g key={i}><circle cx={x} cy={y} r="4" fill="#2979bf"/><text x={x} y={y-12} textAnchor="middle" fontSize="12">{pct(effects[names[i]].accuracy)}</text><text x={x} y="150" textAnchor="middle" fontSize="12">α={i/2}</text></g>)}{effects.random_full&&<><circle cx="500" cy={130-effects.random_full.accuracy*100} r="4" fill="#dd7843"/><text x="490" y="172" textAnchor="end" fontSize="12">同能量随机 α=1：{pct(effects.random_full.accuracy)}</text></>}</svg>;
}

function DocumentContext({index,refs,position}){
  const ref=refs?.[Math.floor(index/32)];const result=useApi(ref?`/api/research-library/artifacts/${ref}`:null);
  if(result.error)return <Empty>{result.error}</Empty>;
  const doc=result.data?.documents.find(r=>r.doc_index===index);
  if(!doc)return <p className="v8-note">读取原始长文…</p>;
  return <><p className="v8-note">{doc.title||doc.doc_id} · {doc.source} · {doc.split} · {doc.license} · 读出 #{position}，实际可见 {position+1} token。{position<512?'短可见前缀：仅作极值探索，不计入长前缀主检验。':'长前缀。'}以下只显示读出时可见的前缀。</p>
    {doc.url&&<a href={doc.url} target="_blank" rel="noreferrer">来源原文与署名</a>}{doc.prefix_texts?.[position]!==undefined?<pre className="v8-sample-text">{doc.prefix_texts[position]}</pre>:<Empty>该位置的可见前缀未归档；请回查分词，不用包含后文的全文替代。</Empty>}
    <details><summary>分词位置、数据版本及原文（含读出之后的内容）</summary><pre className="v8-artifact-json">{JSON.stringify(doc,null,2)}</pre></details></>;
}

export function NativeNeuronCard({sha,documentRefs,referenceTrace}){
  const result=useApi(sha?`/api/research-library/artifacts/${sha}`:null);const [pole,setPole]=useState('2:Gpos'),[error,setError]=useState(0),[open,setOpen]=useState(null);
  if(result.error)return <Empty>{result.error}</Empty>;
  const c=result.data?.card;if(!c)return <Empty>读取原生单元说明书…</Empty>;
  const examples=c.poles[pole]?.examples||[],bad=c.counterexamples[error];
  return <section aria-label="原生MLP单元说明书"><p><strong>B{c.layer} / U{c.unit} · {c.replicated?'两次留出响应预测通过':'未通过两次留出响应预测'}</strong></p>
    {referenceTrace&&<a className="fw-tbtn" href={`?lens=spatial&view=live&trace=${referenceTrace.trace_id}&tblock=${c.layer}&thead=0&tunit=${c.unit}`}>在统一参考长文3D中定位此单元</a>}
    <p className="v8-note">{c.selection==='stratified_random'?'分层随机样本':'历史定向样本（单独统计）'}；A=SiLU(G)×V。解释来源是前缀字符类别统计，尚未得到独立语义标签。</p>
    <table className="v6-table"><thead><tr><th>划分</th><th>排序正确率</th><th>相对随机基线提升（百分点）</th><th>配对 p</th><th>打乱负对照</th></tr></thead><tbody>{[['确认',c.confirm,c.shuffle_confirm],['锁箱',c.lockbox,c.shuffle_lockbox]].map(([s,m,n])=><tr key={s}><td>{s}</td><td>{pct(m.accuracy)}</td><td>{points(m.delta)}</td><td>{num(m.p)}</td><td>{pct(n.accuracy)}</td></tr>)}</tbody></table>
    <details><summary>预测器条目、全层统计与读入/写出</summary><pre className="v8-artifact-json">{JSON.stringify({terms:c.prefix_predictor_terms,population:c.population,alignment:c.read_write_alignment,reader_formula_audit:c.reader_formula_audit,notes:c.alignment_note},null,2)}</pre><p className="v8-note">系数描述固定线性预测器，不自动等于语义。读入与写出方向不同不构成解释失败。</p></details>
    <label>自然语料两极 <select aria-label="神经元两极" value={pole} onChange={e=>{setPole(e.target.value);setOpen(null)}}>{FOLD.flatMap((f,i)=>Object.entries(POLE).map(([k,v])=><option key={`${i}:${k}`} value={`${i}:${k}`}>{f} · {v}</option>))}</select></label>
    <p className="v8-note">每个例子来自不同文档；展示极值用于检索，完整采集包含弱响应。中心化输入方向一致度 {num(c.poles[pole]?.coherence)}，仅作描述。</p>
    {examples.map((r,i)=><div key={`${pole}:${i}`}><button className="fw-tbtn" onClick={()=>setOpen(open===i?null:i)}>文档 {r.doc_index} / #{r.position} · {num(r.value)}</button>{open===i&&<><p className="v8-note">原生 G={num(r.GVA?.G)} · V={num(r.GVA?.V)} · A={num(r.GVA?.A)}</p><DocumentContext index={r.doc_index} position={r.position} refs={documentRefs}/></>}</div>)}
    <details><summary>排序预测反例（共 {c.all_error_count}，保留前 {c.counterexamples.length} 条及全部误差数组）</summary>{bad?<><select aria-label="神经元反例" value={error} onChange={e=>setError(Number(e.target.value))}>{c.counterexamples.map((r,i)=><option value={i} key={i}>配对 {r.pair.a}/{r.pair.b} · #{r.pair.position}</option>)}</select><p>实际 A：{bad.actual.map(num).join(' / ')}；预测 A：{bad.prediction.map(num).join(' / ')}</p><DocumentContext index={bad.pair.a} position={bad.pair.position} refs={documentRefs}/><DocumentContext index={bad.pair.b} position={bad.pair.position} refs={documentRefs}/></>:<p>冻结口径下未保存排序错误；不表示任意语境都成立。</p>}</details>
  </section>;
}

export default function NativeMlpReport({doc:d,planSha,capabilityInputsSha}){
  const [tab,setTab]=useState('result'),[index,setIndex]=useState(0),[layer,setLayer]=useState('all'),[showErrors,setShowErrors]=useState(false);const a=d.analysis,c=d.cards[index];
  const [populationLayer,setPopulationLayer]=useState(0),[fold,setFold]=useState(2),[channel,setChannel]=useState(2),[moment,setMoment]=useState('RMS');
  const popref=d.artifact_refs.population?.[populationLayer];const population=useApi(tab==='population'&&popref?`/api/research-library/artifacts/${popref}`:null);
  const plan=useApi(tab==='source'&&planSha?`/api/research-library/artifacts/${planSha}`:null);
  const rows=d.cards.map((r,i)=>({...r,i})).filter(r=>layer==='all'||r.layer===Number(layer));
  return <section className="v8-intervention-report" aria-label="原生MLP长文本研究报告"><p className="v8-note">{d.run_id} · 本地 Qwen3-4B / BF16 · {d.model_snapshot.slice(0,16)}</p>
    <p><strong>{a.random_replicated}/432 个随机单元通过两次留出响应预测</strong>；{a.random_replicated?'这表示一种有限的上下文规律，尚非单元完整语义或机制解释。':'当前前缀字符类别预测器未通过双留出门；保留负结果，不据此判定单元不可解释。'}</p>
    <div className="v6-toolbar" role="group" aria-label="MLP研究报告内容">{[['result','结果与判据'],['population','全层统计阵列'],['units','单元说明书'],['dose','剂量与能力'],['trace','3D计算路径'],['source','材料与边界']].map(([k,t])=><button key={k} className="fw-tbtn" aria-pressed={tab===k} onClick={()=>setTab(k)}>{t}</button>)}</div>
    {tab==='result'&&<><div className="v8-library-stats"><span><b>2,048</b>自然长文 / 每篇1,024 token</span><span><b>350,208</b>全层单元统计（未全体解释）</span><span><b>{a.random_replicated}/432</b>分层随机单元双留出通过</span></div>
      <p className="v8-note">512 篇确认、512 篇锁箱来自旧普查未使用的维基文档。每次检验 256 对独立文档，读出当前 token 和绝对位置严格相同；模型预训练是否见过原文未知。</p>
      <p>打乱训练响应的负对照双留出通过 {a.random_shuffle_double_pass}/432。历史定向的 34 个单元单独保留。</p>
      <p className="v8-note">固定门：确认与锁箱均提升≥15个百分点、单侧配对 p&lt;0.05/432，且非平局比例≥80%。预测器只读当前 token 与此前文本；词汇/位置基线在配对内相同。</p>
      <p className="v8-note">全部单元保留 G/V/A 均值、平方和、极值与符号分区；466 单元另存逐 token 无损原场。并非对所有 token 保存了全部模块原场。</p></>}
